//! WP-RT-A helper corpora replay (tests/ui/runtime-a/corpora/helpers-*.json, generated by gen-helpers.mjs from the real
//! vue@3.5.43 package). Each case runs in a fresh realm where the global `Vue` namespace is `exports::all`; the target
//! is called through the runtime and its result compared with Node's. A negative control checks that the harness
//! reports a doctored case.

use std::path::PathBuf;

use vn_runtime::exports::install_vue_global;
use vn_testkit::{replay_suite, ReplayOptions, ReplayReport};
use vn_value::Rt;

fn setup(rt: &Rt) {
    install_vue_global(rt);
}

fn corpus(name: &str) -> String {
    let path: PathBuf = [env!("CARGO_MANIFEST_DIR"), "..", "..", "tests", "ui", "runtime-a", "corpora", name].iter().collect();
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn run(text: &str) -> ReplayReport {
    replay_suite(text, &ReplayOptions { setup: Some(setup) })
}

fn assert_clean(file: &str) -> usize {
    let report = run(&corpus(file));
    let first: Vec<String> = report
        .failures
        .iter()
        .take(5)
        .map(|f| format!("{} ({}): expected {} actual {}", f.id, f.reason, f.expected, f.actual))
        .chain(report.missing.iter().take(5).map(|m| format!("missing {} ({})", m.id, m.target)))
        .collect();
    assert!(report.is_clean(), "{file}: passed {} of {}\n{}", report.passed, report.total, first.join("\n"));
    report.total
}

#[test]
fn helpers_class_replays_clean() {
    assert!(assert_clean("helpers-class.json") >= 60);
}

#[test]
fn helpers_style_replays_clean() {
    assert!(assert_clean("helpers-style.json") >= 60);
}

#[test]
fn helpers_display_replays_clean() {
    assert!(assert_clean("helpers-display.json") >= 55);
}

#[test]
fn helpers_names_replays_clean() {
    assert!(assert_clean("helpers-names.json") >= 80);
}

#[test]
fn helpers_merge_replays_clean() {
    assert!(assert_clean("helpers-merge.json") >= 250);
}

#[test]
fn helpers_list_replays_clean() {
    assert!(assert_clean("helpers-list.json") >= 380);
}

#[test]
fn helper_corpora_total_at_least_700_cases() {
    let total: usize = ["helpers-class.json", "helpers-style.json", "helpers-display.json", "helpers-names.json", "helpers-merge.json", "helpers-list.json"]
        .iter()
        .map(|f| run(&corpus(f)).total)
        .sum();
    assert!(total >= 700, "only {total} helper cases");
}

#[test]
fn negative_control_detects_a_wrong_target() {
    // The "array-one" class case run as normalizeStyle must fail: its expected result is a class string.
    let text = corpus("helpers-class.json");
    let at = text.find("array-one").expect("the case exists");
    let key = "\"target\":\"Vue.normalizeClass\"";
    let doctored = format!("{}{}", &text[..at], text[at..].replacen(key, "\"target\":\"Vue.normalizeStyle\"", 1));
    assert_ne!(doctored, text, "the control must change the corpus");
    let report = run(&doctored);
    assert!(!report.failures.is_empty(), "a doctored case must be reported as a failure");
}

#[test]
fn negative_control_per_family_detects_a_doctored_result() {
    // One control per corpus family: an extra element in the first post state makes that case differ from Node.
    for file in ["helpers-class.json", "helpers-style.json", "helpers-display.json", "helpers-names.json", "helpers-merge.json", "helpers-list.json"] {
        let text = corpus(file);
        let doctored = text.replacen("\"state\":[", "\"state\":[{\"$\":\"undef\"},", 1);
        assert_ne!(doctored, text, "{file}: the control must change the corpus");
        let report = run(&doctored);
        assert!(!report.failures.is_empty(), "{file}: a doctored result must be reported as a failure");
    }
}
